    if ((uint64_t)d2_bits_of(sNewSeed) & 3) {
      sSkillArg.nFlags = 0x4025;
    }

    eD2UnitType eUnitType = pUnit->eUnitType;
    sSkillArg.pOwner = pUnit;
    sSkillArg.nMissileTxtNo = nParam5;
